head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.clearFilter();
};
scwin.trigger2_onclick = function(e) {
    scwin.tempFilter = dataList1.getFilterList();
    //alert("저장완료");
    log = "저장완료";
};
scwin.trigger3_onclick = function(e) {
    for (var i = 0; i < scwin.tempFilter.length; i++) {
        dataList1.setColumnFilter(scwin.tempFilter[i]);
        //alert("불러오기완료");
        log1 = "불러오기완료";
    }
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 4. 브라우저에서 임의로 필터를 설정한다. (사용자필터도 같이 설정)
    //4. Set the filter arbitrarily in the browser. (User filter is set as well)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_5_column1_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listRow w2grid_customFilter_list_listRow')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_5_column1_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. 설정한대로 필터가 적용된다.
    //4. The filter is applied as set.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_body_tbody tr').not('.w2grid_hidedRow').length == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. filter_save 버튼을 클릭한다.
    //5. Click the filter_save button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 5. 저장완료 팝업이 생성되면서 현재 설정한 필터가 저장된다.
    //5. The save completed popup is created and the currently set filter is saved.
    WebSquare.wUnit.addCommand("assert", "log == '저장완료'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 6. filter_clear 버튼을 클릭한다.
    //6. Click the filter_clear button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 6. 필터가 초기화된다.
    //6. The filter is initialized.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_5_body_tbody tr').not('.w2grid_hidedRow').length == 11", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 7. filter_load 버튼을 클릭한다.
    //7. Click the filter_load button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 7. 불러오기완료 팝업이 생성되면서 5번에서 저장된 필터가 불러오기된다.
    //7. When the import completion popup is generated, the saved filter is loaded in step # 5.
    WebSquare.wUnit.addCommand("assert", "log1 == '불러오기완료'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.data = [];
    for (var i = 0; i < 20 * 3; i++) {
        data.push(i);
    }
    dataList1.setData(data);
    scwin.tempFilter = [];
    var log, log1;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Mar-2018
    //End unitTest
}
